const CORE_MANIFEST_DATE_START_DATE = "2000-01-01";
const CORE_MANIFEST_DATE_END_DATE = "2099-12-31";
const CORE_MANIFEST_DATE_DIFF_ROW_LIMIT = 40;
const ACCOUNT_SYNC_BRIDGE_PROBE_STORAGE_KEY =
  "zhinote.sync.accountBridgeProbeReceipt.v1";
const ACCOUNT_SYNC_BRIDGE_PROBE_TTL_MS = 30 * 60 * 1000;
const ACCOUNT_SYNC_BRIDGE_PROBE_PRIVACY_NOTE =
  "只读取云端 manifest summary 的 count、deleted、watermark 和状态；不读取页面正文、数据库行值、评论、文件名、文件字节、token 或凭据，也不上传数据、不修改 pending 队列。";
const TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_KEY =
  "zhinote.sync.twoDeviceSmokeOwnerDraft.v1";
const TWO_DEVICE_SMOKE_OWNER_DRAFT_NOTE_LIMIT = 180;
const TWO_DEVICE_SMOKE_OWNER_DRAFT_PRIVACY_NOTE =
  "本地验收草稿只保存 smoke 步骤 ID、通过/失败/阻塞状态和用户手写的脱敏短备注；不要写页面正文、会议链接、文件名、数据库行值、token 或凭据。";
const TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_POLICY =
  "只保存在本机浏览器 localStorage，用于刷新后继续验收；不会上传到云端，不写 sync_log，不作为自动宣称同步通过的证据。";

function buildAccountSyncBridgeProbeDomain(input: {
  id: AccountSyncBridgeProbeDomainId;
  label: string;
  result:
    | CloudPageManifestSummaryResult
    | CloudPageDomainManifestSummaryResult
    | CloudDatabaseManifestSummaryResult;
}): AccountSyncBridgeProbeDomain {
  const { summary } = input.result;
  return {
    id: input.id,
    label: input.label,
    status: input.result.status,
    count: summary?.count ?? null,
    deleted: summary?.deleted ?? null,
    watermark: summary?.watermark ?? null,
    message:
      input.result.status === "ok" && summary
        ? null
        : input.result.message ??
          `云端 ${input.label} manifest summary 暂不可读：${input.result.status}`,
  };
}

function buildAccountSyncBridgeProbeReceipt(input: {
  pages: CloudPageManifestSummaryResult;
  daily: CloudPageDomainManifestSummaryResult;
  meetings: CloudPageDomainManifestSummaryResult;
  databases: CloudDatabaseManifestSummaryResult;
}): AccountSyncBridgeProbeReceipt {
  const checkedAt = new Date();
  const domains: AccountSyncBridgeProbeDomain[] = [
    buildAccountSyncBridgeProbeDomain({
      id: "pages",
      label: "页面",
      result: input.pages,
    }),
    buildAccountSyncBridgeProbeDomain({
      id: "daily",
      label: "每日纪要",
      result: input.daily,
    }),
    buildAccountSyncBridgeProbeDomain({
      id: "meetings",
      label: "会议日历",
      result: input.meetings,
    }),
    buildAccountSyncBridgeProbeDomain({
      id: "databases",
      label: "数据库",
      result: input.databases,
    }),
  ];
  const readableDomains = domains.filter(
    (domain) => domain.status === "ok" && domain.count !== null
  ).length;
  const blockedDomains = domains.length - readableDomains;
  const status: AccountSyncBridgeProbeStatus =
    readableDomains === domains.length
      ? "ready"
      : readableDomains === 0
        ? "blocked"
        : "partial";

  return {
    checked_at: checkedAt.toISOString(),
    expires_at: new Date(
      checkedAt.getTime() + ACCOUNT_SYNC_BRIDGE_PROBE_TTL_MS
    ).toISOString(),
    status,
    readable_domains: readableDomains,
    blocked_domains: blockedDomains,
    domains,
    next_action:
      status === "ready"
        ? "账号同步桥的核心 metadata 均可读；可以继续跑真实两设备 smoke，在另一台设备登录同账号后核对页面、每日、会议和数据库。"
        : "先处理不可读的数据域：通常是未登录、会话过期、同步开关未开、云环境未配置或接口错误；本地输入和 pending 队列会保留。",
    privacy_note: ACCOUNT_SYNC_BRIDGE_PROBE_PRIVACY_NOTE,
    storage_policy:
      "只在本机 localStorage 保留 30 分钟的 metadata-only 检查回执；过期后不作为同步可用证据。",
  };
}

function buildAccountSyncBridgeProbeErrorReceipt(
  message: string
): AccountSyncBridgeProbeReceipt {
  const checkedAt = new Date();
  return {
    checked_at: checkedAt.toISOString(),
    expires_at: new Date(
      checkedAt.getTime() + ACCOUNT_SYNC_BRIDGE_PROBE_TTL_MS
    ).toISOString(),
    status: "blocked",
    readable_domains: 0,
    blocked_domains: 4,
    domains: [
      "pages",
      "daily",
      "meetings",
      "databases",
    ].map((id) => ({
      id: id as AccountSyncBridgeProbeDomainId,
      label:
        id === "pages"
          ? "页面"
          : id === "daily"
            ? "每日纪要"
            : id === "meetings"
              ? "会议日历"
              : "数据库",
      status: "error",
      count: null,
      deleted: null,
      watermark: null,
      message,
    })),
    next_action:
      "只读检查没有完成；先确认账号仍登录、同步接口可访问，再重新运行。这个失败不会上传数据，也不会清空本地队列。",
    privacy_note: ACCOUNT_SYNC_BRIDGE_PROBE_PRIVACY_NOTE,
    storage_policy:
      "只在本机 localStorage 保留 30 分钟的 metadata-only 检查回执；过期后不作为同步可用证据。",
  };
}

function readStoredAccountSyncBridgeProbeReceipt(): AccountSyncBridgeProbeReceipt | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(
      ACCOUNT_SYNC_BRIDGE_PROBE_STORAGE_KEY
    );
    if (!raw) return null;
    const receipt = normalizeAccountSyncBridgeProbeReceipt(JSON.parse(raw));
    if (!receipt || Date.parse(receipt.expires_at) <= Date.now()) {
      window.localStorage.removeItem(ACCOUNT_SYNC_BRIDGE_PROBE_STORAGE_KEY);
      return null;
    }
    return receipt;
  } catch {
    try {
      window.localStorage.removeItem(ACCOUNT_SYNC_BRIDGE_PROBE_STORAGE_KEY);
    } catch {
      // localStorage is optional; losing this UI receipt never affects data.
    }
    return null;
  }
}

function persistAccountSyncBridgeProbeReceipt(
  receipt: AccountSyncBridgeProbeReceipt
): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      ACCOUNT_SYNC_BRIDGE_PROBE_STORAGE_KEY,
      JSON.stringify(receipt)
    );
  } catch {
    // This cache only preserves a UI receipt. Sync correctness does not depend on it.
  }
}

function normalizeAccountSyncBridgeProbeReceipt(
  value: unknown
): AccountSyncBridgeProbeReceipt | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<AccountSyncBridgeProbeReceipt>;
  if (!isAccountSyncBridgeProbeStatus(candidate.status)) return null;
  if (
    typeof candidate.checked_at !== "string" ||
    Number.isNaN(Date.parse(candidate.checked_at)) ||
    typeof candidate.expires_at !== "string" ||
    Number.isNaN(Date.parse(candidate.expires_at)) ||
    typeof candidate.readable_domains !== "number" ||
    typeof candidate.blocked_domains !== "number" ||
    !Array.isArray(candidate.domains) ||
    typeof candidate.next_action !== "string" ||
    typeof candidate.privacy_note !== "string" ||
    typeof candidate.storage_policy !== "string"
  ) {
    return null;
  }
  const domains = candidate.domains
    .map(normalizeAccountSyncBridgeProbeDomain)
    .filter((domain): domain is AccountSyncBridgeProbeDomain =>
      Boolean(domain)
    );
  if (domains.length !== 4) return null;
  return {
    checked_at: candidate.checked_at,
    expires_at: candidate.expires_at,
    status: candidate.status,
    readable_domains: candidate.readable_domains,
    blocked_domains: candidate.blocked_domains,
    domains,
    next_action: candidate.next_action,
    privacy_note: candidate.privacy_note,
    storage_policy: candidate.storage_policy,
  };
}

function normalizeAccountSyncBridgeProbeDomain(
  value: unknown
): AccountSyncBridgeProbeDomain | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<AccountSyncBridgeProbeDomain>;
  if (!isAccountSyncBridgeProbeDomainId(candidate.id)) return null;
  if (
    typeof candidate.label !== "string" ||
    typeof candidate.status !== "string" ||
    (candidate.count !== null && typeof candidate.count !== "number") ||
    (candidate.deleted !== null && typeof candidate.deleted !== "number") ||
    (candidate.watermark !== null && typeof candidate.watermark !== "string") ||
    (candidate.message !== null && typeof candidate.message !== "string")
  ) {
    return null;
  }
  return {
    id: candidate.id,
    label: candidate.label,
    status: candidate.status,
    count: candidate.count,
    deleted: candidate.deleted,
    watermark: candidate.watermark,
    message: candidate.message,
  };
}

function isAccountSyncBridgeProbeStatus(
  value: unknown
): value is AccountSyncBridgeProbeStatus {
  return (
    value === "not-run" ||
    value === "ready" ||
    value === "blocked" ||
    value === "partial"
  );
}

function isAccountSyncBridgeProbeDomainId(
  value: unknown
): value is AccountSyncBridgeProbeDomainId {
  return (
    value === "pages" ||
    value === "daily" ||
    value === "meetings" ||
    value === "databases"
  );
}

function buildEmptyTwoDeviceSmokeOwnerDraft(): TwoDeviceSmokeOwnerDraft {
  return {
    format: "zhinote-two-device-smoke-owner-draft",
    format_version: 1,
    updated_at: new Date().toISOString(),
    steps: {},
    privacy_note: TWO_DEVICE_SMOKE_OWNER_DRAFT_PRIVACY_NOTE,
    storage_policy: TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_POLICY,
  };
}

function readStoredTwoDeviceSmokeOwnerDraft(): TwoDeviceSmokeOwnerDraft | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(
      TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_KEY
    );
    if (!raw) return null;
    return normalizeTwoDeviceSmokeOwnerDraft(JSON.parse(raw));
  } catch {
    return null;
  }
}

function persistTwoDeviceSmokeOwnerDraft(
  draft: TwoDeviceSmokeOwnerDraft
): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_KEY,
      JSON.stringify(draft)
    );
  } catch {
    // This is a local UI checklist only. Sync correctness never depends on it.
  }
}

function updateTwoDeviceSmokeOwnerDraftStep(input: {
  current: TwoDeviceSmokeOwnerDraft | null;
  stepId: string;
  result?: TwoDeviceSmokeOwnerDraftResult;
  note?: string;
}): TwoDeviceSmokeOwnerDraft {
  const now = new Date().toISOString();
  const current = input.current ?? buildEmptyTwoDeviceSmokeOwnerDraft();
  const currentStep = current.steps[input.stepId];
  const nextStep: TwoDeviceSmokeOwnerDraftStep = {
    step_id: input.stepId,
    result:
      input.result ??
      currentStep?.result ??
      ("not-recorded" as TwoDeviceSmokeOwnerDraftResult),
    note:
      input.note !== undefined
        ? sanitizeTwoDeviceSmokeOwnerDraftNote(input.note)
        : currentStep?.note ?? "",
    updated_at: now,
  };
  return {
    ...current,
    updated_at: now,
    steps: {
      ...current.steps,
      [input.stepId]: nextStep,
    },
    privacy_note: TWO_DEVICE_SMOKE_OWNER_DRAFT_PRIVACY_NOTE,
    storage_policy: TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_POLICY,
  };
}

function buildTwoDeviceSmokeOwnerDraftSummary(
  draft: TwoDeviceSmokeOwnerDraft | null,
  stepIds: string[]
): TwoDeviceSmokeOwnerDraftSummary {
  let passed = 0;
  let failed = 0;
  let blocked = 0;
  let notRecorded = 0;
  for (const stepId of stepIds) {
    const result = draft?.steps[stepId]?.result ?? "not-recorded";
    if (result === "pass") {
      passed += 1;
    } else if (result === "fail") {
      failed += 1;
    } else if (result === "blocked") {
      blocked += 1;
    } else {
      notRecorded += 1;
    }
  }
  const status: TwoDeviceSmokeOwnerDraftSummary["status"] =
    failed > 0 || blocked > 0
      ? "has-failures"
      : passed > 0 && notRecorded === 0
        ? "complete"
        : passed > 0
          ? "in-progress"
          : "empty";
  return {
    status,
    total: stepIds.length,
    passed,
    failed,
    blocked,
    not_recorded: notRecorded,
    updated_at: draft?.updated_at ?? null,
  };
}

function getTwoDeviceSmokeOwnerDraftStep(
  draft: TwoDeviceSmokeOwnerDraft | null,
  stepId: string
): TwoDeviceSmokeOwnerDraftStep {
  return (
    draft?.steps[stepId] ?? {
      step_id: stepId,
      result: "not-recorded",
      note: "",
      updated_at: null,
    }
  );
}

function normalizeTwoDeviceSmokeOwnerDraft(
  value: unknown
): TwoDeviceSmokeOwnerDraft | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<TwoDeviceSmokeOwnerDraft>;
  if (
    candidate.format !== "zhinote-two-device-smoke-owner-draft" ||
    candidate.format_version !== 1 ||
    typeof candidate.updated_at !== "string" ||
    !candidate.steps ||
    typeof candidate.steps !== "object" ||
    Array.isArray(candidate.steps)
  ) {
    return null;
  }
  const steps: Record<string, TwoDeviceSmokeOwnerDraftStep> = {};
  for (const [stepId, rawStep] of Object.entries(candidate.steps)) {
    const normalized = normalizeTwoDeviceSmokeOwnerDraftStep(stepId, rawStep);
    if (normalized) steps[stepId] = normalized;
  }
  return {
    format: "zhinote-two-device-smoke-owner-draft",
    format_version: 1,
    updated_at: candidate.updated_at,
    steps,
    privacy_note: TWO_DEVICE_SMOKE_OWNER_DRAFT_PRIVACY_NOTE,
    storage_policy: TWO_DEVICE_SMOKE_OWNER_DRAFT_STORAGE_POLICY,
  };
}

function normalizeTwoDeviceSmokeOwnerDraftStep(
  fallbackStepId: string,
  value: unknown
): TwoDeviceSmokeOwnerDraftStep | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<TwoDeviceSmokeOwnerDraftStep>;
  const result = normalizeTwoDeviceSmokeOwnerDraftResult(candidate.result);
  if (!result) return null;
  return {
    step_id: typeof candidate.step_id === "string" ? candidate.step_id : fallbackStepId,
    result,
    note: sanitizeTwoDeviceSmokeOwnerDraftNote(candidate.note),
    updated_at:
      typeof candidate.updated_at === "string" ? candidate.updated_at : null,
  };
}

function normalizeTwoDeviceSmokeOwnerDraftResult(
  value: unknown
): TwoDeviceSmokeOwnerDraftResult | null {
  return value === "not-recorded" ||
    value === "pass" ||
    value === "fail" ||
    value === "blocked"
    ? value
    : null;
}

function sanitizeTwoDeviceSmokeOwnerDraftNote(value: unknown): string {
  if (typeof value !== "string") return "";
  return value
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, TWO_DEVICE_SMOKE_OWNER_DRAFT_NOTE_LIMIT);
}

function buildEmptyCoreDateManifestDiffReport(): CoreDateManifestDiffReport {
  return {
    comparedDates: 0,
    datesWithDiff: 0,
    rowsShown: 0,
    truncated: false,
    blockedDomains: [],
    rows: [],
    privacyNote:
      "日期级 metadata 对账尚未运行；不会读取标题以外的正文、会议链接、会议号、密码、评论或文件字节。",
  };
}

function buildCoreDateCountMap(
  records: CoreDateManifestRecord[],
  inferDateKey: (title: string, properties: string | null) => string | null
): Map<string, number> {
  const counts = new Map<string, number>();
  for (const record of records) {
    const dateKey = inferDateKey(record.title ?? "", record.properties ?? null);
    if (!dateKey) continue;
    counts.set(dateKey, (counts.get(dateKey) ?? 0) + 1);
  }
  return counts;
}

function buildCoreDateManifestDomainDiffRows(input: {
  domain: CoreDateManifestDomainId;
  title: string;
  localRecords: CoreDateManifestRecord[];
  cloudRecords: CoreDateManifestRecord[];
  inferDateKey: (title: string, properties: string | null) => string | null;
}): { comparedDates: number; rows: CoreDateManifestDiffRow[] } {
  const localCounts = buildCoreDateCountMap(input.localRecords, input.inferDateKey);
  const cloudCounts = buildCoreDateCountMap(input.cloudRecords, input.inferDateKey);
  const dateKeys = Array.from(
    new Set([...localCounts.keys(), ...cloudCounts.keys()])
  ).sort((a, b) => b.localeCompare(a));

  return {
    comparedDates: dateKeys.length,
    rows: dateKeys.map((dateKey) => {
      const localCount = localCounts.get(dateKey) ?? 0;
      const cloudCount = cloudCounts.get(dateKey) ?? 0;
      const delta = localCount - cloudCount;
      const status: CoreDateManifestDiffStatus =
        delta === 0
          ? "matched"
          : cloudCount === 0
            ? "local-extra"
            : localCount === 0
              ? "cloud-extra"
              : "mismatch";
      const nextAction =
        status === "matched"
          ? "日期桶已对齐。"
          : status === "local-extra"
            ? "本地有云端没有的日期桶；先确认 pending queue 是否待补传，避免本地缓存反向覆盖云端。"
            : status === "cloud-extra"
              ? "云端有本地没有的日期桶；优先从云端拉取或重建本地缓存。"
              : "本地和云端同一天数量不同；检查导入重复、日期识别或旧缓存残留。";
      return {
        domain: input.domain,
        title: input.title,
        dateKey,
        localCount,
        cloudCount,
        delta,
        status,
        nextAction,
      };
    }),
  };
}

function buildCoreDateManifestDiffReport(input: {
  daily: {
    localRecords: CoreDateManifestRecord[];
    cloudRecords: CoreDateManifestRecord[];
    cloudStatus: string;
  };
  meetings: {
    localRecords: CoreDateManifestRecord[];
    cloudRecords: CoreDateManifestRecord[];
    cloudStatus: string;
  };
}): CoreDateManifestDiffReport {
  const blockedDomains: string[] = [];
  const domainResults: Array<{
    comparedDates: number;
    rows: CoreDateManifestDiffRow[];
  }> = [];

  if (input.daily.cloudStatus === "ok") {
    domainResults.push(
      buildCoreDateManifestDomainDiffRows({
        domain: "daily",
        title: "每日纪要",
        localRecords: input.daily.localRecords,
        cloudRecords: input.daily.cloudRecords,
        inferDateKey: inferDailyDateKey,
      })
    );
  } else {
    blockedDomains.push(`每日纪要：${input.daily.cloudStatus}`);
  }

  if (input.meetings.cloudStatus === "ok") {
    domainResults.push(
      buildCoreDateManifestDomainDiffRows({
        domain: "meetings",
        title: "会议日历",
        localRecords: input.meetings.localRecords,
        cloudRecords: input.meetings.cloudRecords,
        inferDateKey: inferMeetingDateKey,
      })
    );
  } else {
    blockedDomains.push(`会议日历：${input.meetings.cloudStatus}`);
  }

  const diffRows = domainResults
    .flatMap((result) => result.rows)
    .filter((row) => row.status !== "matched")
    .sort(
      (a, b) =>
        a.domain.localeCompare(b.domain) ||
        b.dateKey.localeCompare(a.dateKey)
    );
  const visibleRows = diffRows.slice(0, CORE_MANIFEST_DATE_DIFF_ROW_LIMIT);

  return {
    comparedDates: domainResults.reduce(
      (total, result) => total + result.comparedDates,
      0
    ),
    datesWithDiff: diffRows.length,
    rowsShown: visibleRows.length,
    truncated: diffRows.length > visibleRows.length,
    blockedDomains,
    rows: visibleRows,
    privacyNote:
      "日期级 metadata 对账只比较每日纪要和会议的日期桶数量；不展示标题、正文、会议链接、会议号、密码、评论或文件字节。",
  };
}

function buildCoreManifestDomainCompare(input: {
  id: CoreManifestDomainCompare["id"];
  title: string;
  localSummary: {
    count: number;
    deleted: number;
    watermark: string;
  };
  cloudResult: {
    status: string;
    summary: {
      count: number;
      deleted: number;
      watermark: string;
    } | null;
    message?: string;
  };
  pending: number;
}): CoreManifestDomainCompare {
  const cloud = input.cloudResult.summary;
  if (input.cloudResult.status !== "ok" || !cloud) {
    const action = buildCoreManifestDomainAction({
      status: "blocked",
      title: input.title,
      pending: input.pending,
    });
    const diffEvidence = buildCoreManifestDiffEvidence({
      localCount: input.localSummary.count,
      cloudCount: null,
      localDeleted: input.localSummary.deleted,
      cloudDeleted: null,
      localWatermark: input.localSummary.watermark,
      cloudWatermark: null,
      pending: input.pending,
      status: "blocked",
    });
    return {
      id: input.id,
      title: input.title,
      localCount: input.localSummary.count,
      cloudCount: null,
      localDeleted: input.localSummary.deleted,
      cloudDeleted: null,
      localWatermark: input.localSummary.watermark,
      cloudWatermark: null,
      pending: input.pending,
      status: "blocked",
      note:
        input.cloudResult.message ??
        `云端 ${input.title} manifest summary 暂不可读：${input.cloudResult.status}`,
      ...diffEvidence,
      ...action,
    };
  }

  const metadataMatches =
    input.localSummary.count === cloud.count &&
    input.localSummary.deleted === cloud.deleted &&
    input.localSummary.watermark === cloud.watermark;
  const status: CoreManifestCompareStatus =
    input.pending > 0 ? "needs-sync" : metadataMatches ? "matched" : "mismatch";
  const action = buildCoreManifestDomainAction({
    status,
    title: input.title,
    pending: input.pending,
  });
  const diffEvidence = buildCoreManifestDiffEvidence({
    localCount: input.localSummary.count,
    cloudCount: cloud.count,
    localDeleted: input.localSummary.deleted,
    cloudDeleted: cloud.deleted,
    localWatermark: input.localSummary.watermark,
    cloudWatermark: cloud.watermark,
    pending: input.pending,
    status,
  });

  return {
    id: input.id,
    title: input.title,
    localCount: input.localSummary.count,
    cloudCount: cloud.count,
    localDeleted: input.localSummary.deleted,
    cloudDeleted: cloud.deleted,
    localWatermark: input.localSummary.watermark,
    cloudWatermark: cloud.watermark,
    pending: input.pending,
    status,
    note:
      status === "matched"
        ? "本地热缓存 metadata 与云端 manifest summary 对齐。"
        : status === "needs-sync"
          ? "本地还有 pending 变更，先补传再判断是否需要重建缓存。"
          : "本地热缓存和云端 manifest 的 count 或 watermark 不一致，需要同步、拉取或重建缓存。",
    ...diffEvidence,
    ...action,
  };
}

function buildCoreManifestDiffEvidence(input: {
  localCount: number;
  cloudCount: number | null;
  localDeleted: number;
  cloudDeleted: number | null;
  localWatermark: string;
  cloudWatermark: string | null;
  pending: number;
  status: CoreManifestCompareStatus;
}): Pick<
  CoreManifestDomainCompare,
  | "countDelta"
  | "deletedDelta"
  | "watermarkMatches"
  | "diffReasons"
  | "reviewChecklist"
> {
  const countDelta =
    input.cloudCount === null ? null : input.localCount - input.cloudCount;
  const deletedDelta =
    input.cloudDeleted === null ? null : input.localDeleted - input.cloudDeleted;
  const watermarkMatches =
    input.cloudWatermark === null
      ? null
      : input.localWatermark === input.cloudWatermark;
  const diffReasons: string[] = [];
  if (input.status === "blocked") {
    diffReasons.push("云端 manifest 暂不可读，无法证明云端主库完整。");
  }
  if (input.pending > 0) {
    diffReasons.push(
      `本地还有 ${input.pending} 条 pending 变更，必须先补传或冻结。`
    );
  }
  if (countDelta !== null && countDelta !== 0) {
    diffReasons.push(
      countDelta > 0
        ? `本地比云端多 ${countDelta} 条 metadata。`
        : `本地比云端少 ${Math.abs(countDelta)} 条 metadata。`
    );
  }
  if (deletedDelta !== null && deletedDelta !== 0) {
    diffReasons.push(
      deletedDelta > 0
        ? `本地删除标记比云端多 ${deletedDelta} 条。`
        : `本地删除标记比云端少 ${Math.abs(deletedDelta)} 条。`
    );
  }
  if (watermarkMatches === false) {
    diffReasons.push("本地和云端 watermark 不一致，说明更新时间游标不同。");
  }
  if (diffReasons.length === 0) {
    diffReasons.push("count、deleted 和 watermark 均已对齐。");
  }

  const reviewChecklist =
    input.status === "matched"
      ? ["缓存可按云端 manifest 重建；无需上传本地缓存。"]
      : input.status === "needs-sync"
        ? [
            "先补传 pending queue 中的本地修改。",
            "补传后重新运行只读检查。",
            "确认本地未上传编辑没有被云端旧值覆盖。",
          ]
        : input.status === "mismatch"
          ? [
              "导出本地/云端 manifest 差异。",
              "确认差异来自新增、删除、导入重复还是旧缓存。",
              "人工确认后才允许从云端重建本地缓存。",
            ]
          : [
              "先恢复登录、环境变量或云端 manifest API。",
              "确认没有读取正文、文件字节或数据库值。",
              "云端可读后重新运行只读检查。",
            ];

  return {
    countDelta,
    deletedDelta,
    watermarkMatches,
    diffReasons,
    reviewChecklist,
  };
}

function buildCoreManifestDomainAction(input: {
  status: CoreManifestCompareStatus;
  title: string;
  pending: number;
}): Pick<
  CoreManifestDomainCompare,
  | "rebuildGate"
  | "canRebuildFromCloudManifest"
  | "ownerReviewRequired"
  | "nextAction"
  | "safetyInvariant"
> {
  const safetyInvariant =
    "云端 manifest 是重建来源；本地缓存只是复印件，不能反向覆盖云端。";
  if (input.status === "blocked") {
    return {
      rebuildGate: "blocked",
      canRebuildFromCloudManifest: false,
      ownerReviewRequired: true,
      nextAction: `先修复 ${input.title} 的登录、环境变量或云端 manifest 可读性，再允许任何缓存重建。`,
      safetyInvariant,
    };
  }
  if (input.status === "needs-sync") {
    return {
      rebuildGate: "pending-first",
      canRebuildFromCloudManifest: false,
      ownerReviewRequired: true,
      nextAction: `先补传 ${input.pending} 条本地 pending 变更；未上传编辑必须保留，不能被云端旧值覆盖。`,
      safetyInvariant,
    };
  }
  if (input.status === "mismatch") {
    return {
      rebuildGate: "manual-review",
      canRebuildFromCloudManifest: true,
      ownerReviewRequired: true,
      nextAction: `先导出 ${input.title} 的本地/云端 manifest 差异，人工确认后再从云端重建本地缓存。`,
      safetyInvariant,
    };
  }
  return {
    rebuildGate: "cloud-rebuild-ready",
    canRebuildFromCloudManifest: true,
    ownerReviewRequired: false,
    nextAction: `${input.title} 已对齐；如果本地缓存损坏，可按云端 manifest 重建，不需要上传本地缓存。`,
    safetyInvariant,
  };
}

function getCoreManifestOverallStatus(
  domains: CoreManifestDomainCompare[]
): CoreManifestCompareReport["status"] {
  if (domains.some((domain) => domain.status === "blocked")) return "blocked";
  if (domains.some((domain) => domain.status === "needs-sync")) {
    return "needs-sync";
  }
  if (domains.some((domain) => domain.status === "mismatch")) return "mismatch";
  return "matched";
}

function buildCoreManifestCompareSummary(
  domains: CoreManifestDomainCompare[],
  dateDiffReport: CoreDateManifestDiffReport = buildEmptyCoreDateManifestDiffReport()
): CoreManifestCompareReport["summary"] {
  return {
    matched: domains.filter((domain) => domain.status === "matched").length,
    needsSync: domains.filter((domain) => domain.status === "needs-sync")
      .length,
    mismatch: domains.filter((domain) => domain.status === "mismatch").length,
    blocked: domains.filter((domain) => domain.status === "blocked").length,
    rebuildReady: domains.filter(
      (domain) => domain.rebuildGate === "cloud-rebuild-ready"
    ).length,
    ownerReviewRequired: domains.filter((domain) => domain.ownerReviewRequired)
      .length,
    pendingRows: domains.reduce((total, domain) => total + domain.pending, 0),
    absoluteCountDelta: domains.reduce(
      (total, domain) => total + Math.abs(domain.countDelta ?? 0),
      0
    ),
    absoluteDeletedDelta: domains.reduce(
      (total, domain) => total + Math.abs(domain.deletedDelta ?? 0),
      0
    ),
    domainsWithWatermarkMismatch: domains.filter(
      (domain) => domain.watermarkMatches === false
    ).length,
    dateBucketsCompared: dateDiffReport.comparedDates,
    dateBucketsWithDiff: dateDiffReport.datesWithDiff,
    dateDiffRowsShown: dateDiffReport.rowsShown,
  };
}

function withCoreManifestCompareReceipt(
  report: Omit<CoreManifestCompareReport, "receipt">
): CoreManifestCompareReport {
  return {
    ...report,
    receipt: buildCoreManifestCompareReceipt(report),
  };
}

