        if (!mounted) return;
        setWorkspaceIdentity(loadedIdentity);
        setDatabases(loadedDatabases);
        setDeletedPages(loadedDeletedPages);
        setStoredFiles(loadedFiles);
        setPageModuleCounts(loadedPageModuleCounts);
        setSyncSummary(loadedSync);
