function summarizeFiles(files: StoredPageFile[]) {
  const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
  const kindCounts = files.reduce<Partial<Record<StoredPageFile["kind"], number>>>(
    (counts, file) => {
    counts[file.kind] = (counts[file.kind] ?? 0) + 1;
    return counts;
    },
    {}
  );

  return {
    totalSize: formatBytes(totalBytes),
    kinds: Object.entries(kindCounts)
      .map(([kind, count]) => ({
        kind: kind as StoredPageFile["kind"],
        count: Number(count ?? 0),
      }))
      .sort((a, b) => b.count - a.count || a.kind.localeCompare(b.kind)),
  };
}

function formatBytes(bytes: number) {
  if (bytes <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB"];
  let value = bytes;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }
  return `${value.toFixed(value >= 10 || unitIndex === 0 ? 0 : 1)} ${
    units[unitIndex]
  }`;
}

class SyncCloudApiRequestTimeoutError extends Error {
  timeoutMs: number;

  constructor(timeoutMs: number) {
    super("云端请求超时；本地输入和待上传队列已保留，可稍后重试。");
    this.name = "SyncCloudApiRequestTimeoutError";
    this.timeoutMs = timeoutMs;
  }
}

async function fetchSyncCloudApiWithTimeout(
  input: Parameters<typeof fetch>[0],
  init?: Parameters<typeof fetch>[1]
): Promise<Response> {
  const freshInit = await withFreshCloudAuthorization(init);
  const controller = new AbortController();
  let didTimeout = false;
  const timeout = window.setTimeout(() => {
    didTimeout = true;
    controller.abort();
  }, SYNC_CLOUD_API_REQUEST_TIMEOUT_MS);

  try {
    return await fetch(input, {
      ...freshInit,
      cache: freshInit?.cache ?? "no-store",
      signal: controller.signal,
    });
  } catch (error) {
    if (didTimeout) {
      throw new SyncCloudApiRequestTimeoutError(
        SYNC_CLOUD_API_REQUEST_TIMEOUT_MS
      );
    }
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

async function withFreshCloudAuthorization(
  init?: Parameters<typeof fetch>[1]
): Promise<Parameters<typeof fetch>[1]> {
  const headers = new Headers(init?.headers);
  const authorization = headers.get("Authorization");
  const session = readCloudSession();
  if (!authorization || !session) {
    return init;
  }

  if (!isCloudSessionExpired(session)) {
    if (authorization !== `Bearer ${session.accessToken}`) {
      return {
        ...init,
        headers: withCloudAuthorization(headers, session.accessToken),
      };
    }
    return init;
  }

  const result = await refreshCloudSession(session);
  if (result.status !== "refreshed") {
    throw new Error(
      `云端 session 自动续期失败：${result.error}。本地数据和待上传队列已保留，请稍后重试或重新登录。`
    );
  }
  return {
    ...init,
    headers: withCloudAuthorization(headers, result.session.accessToken),
  };
}

function withCloudAuthorization(headers: Headers, accessToken: string): Headers {
  headers.set("Authorization", `Bearer ${accessToken}`);
  return headers;
}

async function readCloudApiBody(response: Response) {
  const text = await response.text();
  if (!text) return null;

  try {
    return JSON.parse(text) as Record<string, unknown>;
  } catch {
    return {
      message: text,
    };
  }
}

function getCloudCallbackHandoffMessage(
  status: string | null
): CloudAlphaMessage {
  if (status === "recovered") {
    return {
      tone: "success",
      title: "云接力已恢复",
      detail:
        "本地云 session 已保存，并已把这台设备接回云 workspace。这里只恢复账号/workspace metadata，没有上传本地内容。",
    };
  }

  if (status === "workspace-choice") {
    return {
      tone: "warning",
      title: "请选择云工作区",
      detail:
        "本地云 session 已保存。账号下有多个 workspace，为避免接错研究空间，请先选择一个再恢复云接力；不会自动上传本地内容。",
    };
  }

  if (status === "no-workspace") {
    return {
      tone: "info",
      title: "云端登录已连接",
      detail:
        "本地云 session 已保存，但当前账号还没有可恢复的云 workspace。可以创建空 workspace；本地内容仍在本机。",
    };
  }

  if (status === "metadata-unavailable" || status === "failed") {
    return {
      tone: "warning",
      title: "云端登录已保存",
      detail:
        "登录没有丢失，但自动恢复云接力暂时没有完成。可以继续本地使用，稍后在同步中心点“恢复云接力”重试。",
    };
  }

  return {
    tone: "success",
    title: "云端登录已连接",
    detail:
      "本地云 session 已保存。下一步可以恢复云接力或创建一个空的云 workspace。",
  };
}

function getCloudApiDetail(
  body: Record<string, unknown> | null,
  response: Response
) {
  const message = getRecordString(body, "message");
  if (message) return message;

  const error = getRecordString(body, "error");
  const configStatus = getRecordString(body, "cloud_config_status");
  const missing = getStringArray(body?.missing_env);
  if (configStatus && missing.length > 0) {
    return `${configStatus}: ${missing.join(", ")}`;
  }

  const purpose = getRecordString(body, "purpose");
  if (purpose) return purpose;

  if (error) return error;
  return `HTTP ${response.status}`;
}

function getCloudSessionUser(body: Record<string, unknown> | null) {
  const user = getRecordValue(body, "user");
  if (!user) return null;
  const id = getRecordString(user, "id");
  const emailValue = user.email;
  if (!id) return null;

  return {
    id,
    email: typeof emailValue === "string" ? emailValue : null,
  };
}

function getCloudWorkspace(body: Record<string, unknown> | null) {
  const workspace = getRecordValue(body, "workspace");
  if (!workspace) return null;
  const id = getRecordString(workspace, "id");
  const name = getRecordString(workspace, "name");
  const betaStatus = getRecordString(workspace, "beta_status");
  if (!id || !name) return null;

  return {
    id,
    name,
    beta_status: betaStatus || "private-alpha",
    created_at: getRecordString(workspace, "created_at") || undefined,
    updated_at: getRecordString(workspace, "updated_at") || undefined,
  } satisfies CloudAlphaWorkspace;
}

function getCloudWorkspaces(body: Record<string, unknown> | null) {
  const value = body?.workspaces;
  if (!Array.isArray(value)) return [];

  const workspaces: CloudAlphaWorkspace[] = [];
  for (const item of value) {
    if (!item || typeof item !== "object") continue;
    const record = item as Record<string, unknown>;
    const id = getRecordString(record, "id");
    const name = getRecordString(record, "name");
    if (!id || !name) continue;

    workspaces.push({
      id,
      name,
      beta_status: getRecordString(record, "beta_status") || "private-alpha",
      role: getCloudRole(record.role),
      membership_created_at:
        getRecordString(record, "membership_created_at") || undefined,
      created_at: getRecordString(record, "created_at") || undefined,
      updated_at: getRecordString(record, "updated_at") || undefined,
    });
  }

  return workspaces;
}

function getCloudMembership(body: Record<string, unknown> | null) {
  const membership = getRecordValue(body, "membership");
  if (!membership) return null;

  return {
    user_id: getRecordString(membership, "user_id"),
    role: getCloudRole(membership.role),
  };
}

function getCloudModuleCount(body: Record<string, unknown> | null) {
  const modules = body?.modules;
  return Array.isArray(modules) ? modules.length : 0;
}

function getCloudSyncState(body: Record<string, unknown> | null) {
  const sync = getRecordValue(body, "sync");
  return {
    push_enabled: getRecordBoolean(sync, "push_enabled"),
    pull_enabled: getRecordBoolean(sync, "pull_enabled"),
  };
}

function upsertCloudWorkspace(
  current: CloudAlphaWorkspace[],
  workspace: CloudAlphaWorkspace
) {
  const index = current.findIndex((item) => item.id === workspace.id);
  if (index === -1) return [workspace, ...current];
  return current.map((item) => (item.id === workspace.id ? workspace : item));
}

function getCloudRole(
  value: unknown
): "owner" | "researcher" | "viewer" | undefined {
  return value === "owner" || value === "researcher" || value === "viewer"
    ? value
    : undefined;
}

function getRecordString(
  record: Record<string, unknown> | null,
  key: string
) {
  const value = record?.[key];
  return typeof value === "string" ? value : "";
}

function getRecordBoolean(
  record: Record<string, unknown> | null,
  key: string
) {
  const value = record?.[key];
  return typeof value === "boolean" ? value : false;
}

function getRecordValue(
  record: Record<string, unknown> | null,
  key: string
) {
  const value = record?.[key];
  return value && typeof value === "object"
    ? (value as Record<string, unknown>)
    : null;
}

function getStringArray(value: unknown) {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
}

function isValidCloudEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function formatPageSyncStatus(status: string) {
  if (status === "unauthenticated") return "账号未登录";
  if (status === "unconfigured") return "云端未配置";
  if (status === "unconfirmed") return "账号临时不可确认";
  if (status === "ok") return "同步完成";
  if (status === "disabled") return "页面同步已关闭";
  if (status === "error") return "云端同步错误";
  return status;
}

function formatPageSyncOutcomeSource(source: string) {
  if (source === "direct-push") return "直接上传";
  if (source === "pending-push") return "pending 补传";
  if (source === "sync-log-push") return "sync_log 补传";
  if (source === "baseline-upload") return "首次基线补种";
  if (source === "reconcile") return "页面同步对账";
  return source;
}

function formatDatabaseSyncStatus(status: string) {
  if (status === "unauthenticated") return "账号未登录";
  if (status === "unconfigured") return "云端未配置";
  if (status === "unconfirmed") return "账号临时不可确认";
  if (status === "ok") return "同步完成";
  if (status === "disabled") return "数据库同步已关闭";
  if (status === "error") return "云端同步错误";
  return status;
}

function formatDatabaseSyncOutcomeSource(source: string) {
  if (source === "direct-push") return "直接上传";
  if (source === "pending-push") return "pending 补传";
  if (source === "sync-log-push") return "sync_log 补传";
  if (source === "baseline-upload") return "首次基线补种";
  if (source === "reconcile") return "数据库同步对账";
  return source;
}

function appendSyncOutcomeMessage(detail: string, message?: string | null) {
  const cleanMessage = message?.trim();
  return cleanMessage ? `${detail} 最近原因：${cleanMessage}` : detail;
}

function formatFileEmbedSyncOutcomeStatus(status: string) {
  if (status === "ok") return "补传完成";
  if (status === "partial") return "部分完成";
  if (status === "failed") return "补传失败";
  if (status === "deferred") return "等待账号确认";
  return status;
}

function formatFileEmbedSyncOutcomeSource(source: string) {
  if (source === "queue-drain") return "文件队列补传";
  return source;
}

function formatSyncAuthRetryStatus(status: string) {
  if (status === "unauthenticated") return "账号未登录";
  if (status === "unconfigured") return "云端未配置";
  if (status === "unconfirmed") return "账号临时不可确认";
  if (status === "disabled") return "同步已关闭";
  if (status === "error") return "云端同步错误";
  return status;
}

function isPageSyncStorageEvent(event: StorageEvent): boolean {
  return Boolean(
    event.key && event.key.startsWith(PAGE_SYNC_STORAGE_KEY_PREFIX)
  );
}

function isDatabaseSyncStorageEvent(event: StorageEvent): boolean {
  return Boolean(
    event.key && event.key.startsWith(DATABASE_SYNC_STORAGE_KEY_PREFIX)
  );
}

function isSyncStatusStorageEvent(event: StorageEvent): boolean {
  return (
    event.key === SYNC_LOG_STATUS_STORAGE_KEY ||
    event.key === SETTINGS_SYNC_STATUS_STORAGE_KEY ||
    event.key === KNOWLEDGE_SYNC_STATUS_STORAGE_KEY
  );
}

function isActivePagePendingStatus(status: PendingCloudPageSyncStatus): boolean {
  return (
    status.pending +
      status.queued +
      (status.syncLogPending ?? 0) +
      status.failed +
      status.manualReviewCount >
    0
  );
}

function isActiveDatabasePendingStatus(
  status: PendingCloudDatabaseSyncStatus
): boolean {
  return (
    status.pending +
      status.queued +
      (status.syncLogPending ?? 0) +
      status.failed +
      status.manualReviewCount >
    0
  );
}

function formatPerformanceStatus(status: string) {
  const labels: Record<string, string> = {
    "cloud-ok": "云端补齐完成",
    "cloud-disabled": "云端关闭",
    "cloud-unauthenticated": "未登录",
    "cloud-unconfigured": "云端未配置",
    "cloud-error": "云端读取失败",
    "local-refresh": "本地刷新",
    "content-ready": "正文可用",
    "metadata-ready": "metadata 可用",
    "local-body-ready": "本地正文补齐",
    "cloud-body-ready": "云端正文补齐",
    "empty-ready": "空正文可编辑",
    unavailable: "正文暂不可用",
  };
  return labels[status] ?? status;
}

function formatPerformanceMs(value: number | null | undefined) {
  if (typeof value !== "number" || !Number.isFinite(value)) return "暂无";
  if (value >= 1000) return `${(value / 1000).toFixed(1)}s`;
  return `${Math.round(value)}ms`;
}

function averagePerformanceMs(
  snapshots: LocalPerformanceSnapshot[],
  kind: LocalPerformanceSnapshot["kind"]
) {
  const values = snapshots
    .filter((snapshot) => snapshot.kind === kind)
    .map((snapshot) => snapshot.duration_ms)
    .filter((value) => Number.isFinite(value));
  if (values.length === 0) return null;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function formatPerformanceCounts(counts: Record<string, number>) {
  const entries = Object.entries(counts).slice(0, 4);
  if (entries.length === 0) return "无";
  return entries.map(([key, value]) => `${key}: ${value}`).join(" · ");
}

function formatDate(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString();
}

function downloadJsonFile(fileName: string, value: unknown) {
  const blob = new Blob([JSON.stringify(value, null, 2)], {
    type: "application/json;charset=utf-8",
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function fileSafeTimestamp() {
  return new Date().toISOString().replace(/[:.]/g, "-");
}
